from __future__ import annotations

from dataclasses import asdict, dataclass
from typing import Any

from sqlalchemy import text
from sqlalchemy.orm import Session


# Tables whose contents are generated by Stage 2 or by operational wrappers
# around Stage 2.  The list is intentionally explicit.  Do not replace it with
# TRUNCATE ... CASCADE: the preserved identity/archive layer is the boundary of
# this maintenance operation.
STAGE2_DERIVED_TABLES: tuple[str, ...] = (
    "artifact_publications",
    "artifacts",
    "interseries_calibration_edges",
    "interseries_calibration_series",
    "interseries_calibration_generations",
    "science_photometry",
    "event_frame_coverage",
    "event_detection_links",
    "object_qc",
    "calibration_frame_terms",
    "calibration_iteration_objects",
    "calibration_iterations",
    "calibration_product_aliases",
    "measurements",
    "calibration_versions",
    "detection_catalog_matches",
    "source_detections",
    "detection_run_frames",
    "detection_runs",
    "frame_qc",
    "frame_catalog_links",
    "pipeline_log_events",
    "pipeline_run_steps",
    "batch_job_attempts",
    "batch_jobs",
    "batch_inventory_items",
    "batch_runs",
    "pipeline_runs",
    "processing_events",
)

PRESERVED_TABLES: tuple[str, ...] = (
    "schema_migrations",
    "instrument_units",
    "observations",
    "frames",
    "fields",
    "field_series",
    "field_series_frames",
    "catalog_sources",
    "reference_photometry_catalogs",
    "photometric_bands",
    "reference_photometry_sources",
    "reference_photometry_points",
    "objects",
    "event_registry",
    "event_object_links",
)

FRAME_RESET_KEYS: tuple[str, ...] = (
    "wcs_check",
    "frame_pre_photometry_qc_v1",
    "BAD_PRE_PHOTOMETRY_QC",
    "detection_catalog_qc",
)

SERIES_METADATA_RESET_KEYS: tuple[str, ...] = (
    "last_pipeline_run_id",
    "last_run_uid",
    "last_pipeline_status",
    "last_error_message",
)


@dataclass(frozen=True)
class TableResetRow:
    table_name: str
    rows_before: int
    action: str

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


@dataclass(frozen=True)
class PreservedTableRow:
    table_name: str
    rows: int

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


@dataclass(frozen=True)
class Stage2ResetAudit:
    derived: list[TableResetRow]
    preserved: list[PreservedTableRow]
    n_frames_to_reset: int
    n_series_to_reset: int
    n_fields_to_reset: int

    @property
    def total_derived_rows(self) -> int:
        return sum(row.rows_before for row in self.derived)

    def to_dict(self) -> dict[str, Any]:
        return {
            "scope": "stage2",
            "mode": "all_series",
            "total_derived_rows": self.total_derived_rows,
            "n_frames_to_reset": self.n_frames_to_reset,
            "n_series_to_reset": self.n_series_to_reset,
            "n_fields_to_reset": self.n_fields_to_reset,
            "derived": [row.to_dict() for row in self.derived],
            "preserved": [row.to_dict() for row in self.preserved],
        }


@dataclass(frozen=True)
class Stage2ResetResult:
    audit: Stage2ResetAudit
    executed: bool
    frames_reset: int = 0
    series_reset: int = 0
    fields_reset: int = 0

    def to_dict(self) -> dict[str, Any]:
        payload = self.audit.to_dict()
        payload.update(
            {
                "executed": self.executed,
                "frames_reset": self.frames_reset,
                "series_reset": self.series_reset,
                "fields_reset": self.fields_reset,
            }
        )
        return payload


def audit_stage2_reset(session: Session) -> Stage2ResetAudit:
    """Return a read-only inventory for the global Stage-2 derived-data reset."""

    derived = [
        TableResetRow(table_name=name, rows_before=_table_count(session, name), action="TRUNCATE")
        for name in STAGE2_DERIVED_TABLES
    ]
    preserved = [
        PreservedTableRow(table_name=name, rows=_table_count(session, name))
        for name in PRESERVED_TABLES
    ]
    n_frames = int(
        session.execute(
            text(
                """
                SELECT COUNT(DISTINCT fsf.frame_id)::bigint
                FROM field_series_frames fsf
                """
            )
        ).scalar_one()
        or 0
    )
    n_series = int(session.execute(text("SELECT COUNT(*)::bigint FROM field_series")).scalar_one() or 0)
    n_fields = int(session.execute(text("SELECT COUNT(*)::bigint FROM fields")).scalar_one() or 0)
    return Stage2ResetAudit(
        derived=derived,
        preserved=preserved,
        n_frames_to_reset=n_frames,
        n_series_to_reset=n_series,
        n_fields_to_reset=n_fields,
    )


def reset_stage2_derived_data(session: Session) -> Stage2ResetResult:
    """Atomically remove all Stage-2 derived rows while preserving archive identity.

    The caller owns commit/rollback.  PostgreSQL ``TRUNCATE`` is transactional,
    so a failure in any following state reset can still be rolled back by the
    caller.  Sequences deliberately continue rather than restart: old filesystem
    log/manifests may still contain historical numeric IDs and must never collide
    with newly generated rows.
    """

    audit = audit_stage2_reset(session)

    table_sql = ",\n    ".join(STAGE2_DERIVED_TABLES)
    session.execute(
        text(
            f"""
            TRUNCATE TABLE
                {table_sql}
            CONTINUE IDENTITY
            """
        )
    )

    # Reset only the execution/QC state of frames already assigned to observing
    # series.  FITS paths, headers, astrometric center coordinates, instrument
    # metadata, and raw calibration-reference status columns remain untouched.
    frame_result = session.execute(
        text(
            """
            UPDATE frames fr
            SET processing_status = 'HEADER_READ',
                wcs_status = 'NOT_CHECKED',
                quality_flags = COALESCE(fr.quality_flags, '{}'::jsonb)
                    - 'wcs_check'
                    - 'frame_pre_photometry_qc_v1'
                    - 'BAD_PRE_PHOTOMETRY_QC'
                    - 'detection_catalog_qc',
                updated_at = now()
            WHERE EXISTS (
                SELECT 1
                FROM field_series_frames fsf
                WHERE fsf.frame_id = fr.frame_id
            )
            """
        )
    )

    series_result = session.execute(
        text(
            """
            UPDATE field_series
            SET status = 'READY',
                metadata_json = COALESCE(metadata_json, '{}'::jsonb)
                    - 'last_pipeline_run_id'
                    - 'last_run_uid'
                    - 'last_pipeline_status'
                    - 'last_error_message',
                updated_at = now()
            """
        )
    )
    fields_result = session.execute(
        text(
            """
            UPDATE fields
            SET status = 'READY',
                updated_at = now()
            """
        )
    )

    return Stage2ResetResult(
        audit=audit,
        executed=True,
        frames_reset=max(int(frame_result.rowcount or 0), 0),
        series_reset=max(int(series_result.rowcount or 0), 0),
        fields_reset=max(int(fields_result.rowcount or 0), 0),
    )


def _table_count(session: Session, table_name: str) -> int:
    # All names come from module-level constants; there is no user-controlled
    # identifier interpolation here.
    value = session.execute(text(f"SELECT COUNT(*)::bigint FROM {table_name}")).scalar_one()
    return int(value or 0)
